{"file_path":"src/sheet.js","content":"/**
 * Reading a sheet: cell addresses and the line format.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/**
 * Parses `text` as a cell address. Returns `{ name, col, row }` with the name
 * upper-cased and normalised, or null when the address is outside the
 * addressable range.
 */
export function parseAddress(text) {
  const match = ADDRESS_RE.exec(text)
  if (match === null) return null
  const row = Number(match[2])
  if (row < 1) return null
  const letters = match[1].toUpperCase()
  let col = 0
  for (let i = 0; i < letters.length; i++) col = col * 26 + (letters.charCodeAt(i) - 64)
  return { name: letters + String(row), col, row }
}

/** Orders two cells by column and then by row. */
export function compareCells(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}

const SPACE = /[ \t]/

/**
 * Splits the sheet read from standard input into its cells. Returns
 * `{ cells }` on success, or `{ error }` with the message of the first
 * failure.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index]
    const lineNumber = index + 1
    let at = 0
    while (at < line.length && SPACE.test(line[at])) at++
    if (at >= line.length) continue
    if (line[at] === '#') continue

    const start = at
    while (at < line.length && !SPACE.test(line[at])) at++
    const raw = line.slice(start, at)
    while (at < line.length && SPACE.test(line[at])) at++
    const content = line.slice(at)

    const address = parseAddress(raw)
    if (address === null) {
      return { error: `line ${lineNumber}: invalid cell address ${raw.toUpperCase()}` }
    }
    if (cells.has(address.name)) {
      return { error: `line ${lineNumber}: cell ${address.name} is declared twice` }
    }
    cells.set(address.name, { name: address.name, col: address.col, row: address.row, content })
  }
  return { cells }
}

/** The declared cells in printing order. */
export function orderedCells(cells) {
  return [...cells.values()].sort(compareCells)
}
"}

