{"file_path":"src/parser.js","content":"/**
 * The formula grammar: a tokeniser and a recursive descent parser producing
 * the tree a formula body describes, or null when the body is not a formula.
 */

const isDigit = (c) => c >= '0' && c <= '9'
const isLetter = (c) => (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')

const PUNCTUATION = ['^', '*', '/', '+', '-', '=', '<', '>', '(', ')', ',', ':']

/** Splits a formula body into tokens, or returns null on an unknown character. */
export function tokenize(source) {
  const tokens = []
  let i = 0
  while (i < source.length) {
    const c = source[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (isDigit(c)) {
      let j = i
      while (j < source.length && isDigit(source[j])) j++
      if (source[j] === '.' && isDigit(source[j + 1])) {
        j++
        while (j < source.length && isDigit(source[j])) j++
      }
      tokens.push({ kind: 'number', text: source.slice(i, j) })
      i = j
      continue
    }
    if (isLetter(c)) {
      let j = i
      while (j < source.length && isLetter(source[j])) j++
      while (j < source.length && isDigit(source[j])) j++
      tokens.push({ kind: 'word', text: source.slice(i, j) })
      i = j
      continue
    }
    if (c === '<' && (source[i + 1] === '>' || source[i + 1] === '=')) {
      tokens.push({ kind: 'op', text: source.slice(i, i + 2) })
      i += 2
      continue
    }
    if (c === '>' && source[i + 1] === '=') {
      tokens.push({ kind: 'op', text: '>=' })
      i += 2
      continue
    }
    if (PUNCTUATION.includes(c)) {
      tokens.push({ kind: 'op', text: c })
      i++
      continue
    }
    return null
  }
  return tokens
}

const COMPARISONS = ['=', '<>', '<', '<=', '>', '>=']

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.at = 0
  }

  peek(offset = 0) {
    return this.tokens[this.at + offset]
  }

  isOp(text, offset = 0) {
    const token = this.peek(offset)
    return token !== undefined && token.kind === 'op' && token.text === text
  }

  take() {
    return this.tokens[this.at++]
  }

  comparison() {
    let left = this.additive()
    for (;;) {
      const token = this.peek()
      if (token === undefined || token.kind !== 'op' || !COMPARISONS.includes(token.text)) return left
      this.take()
      const right = this.additive()
      left = { kind: 'compare', op: token.text, left, right }
    }
  }

  additive() {
    let left = this.multiplicative()
    for (;;) {
      if (!this.isOp('+') && !this.isOp('-')) return left
      const op = this.take().text
      const right = this.multiplicative()
      left = { kind: 'binary', op, left, right }
    }
  }

  multiplicative() {
    let left = this.power()
    for (;;) {
      if (!this.isOp('*') && !this.isOp('/')) return left
      const op = this.take().text
      const right = this.power()
      left = { kind: 'binary', op, left, right }
    }
  }

  power() {
    const base = this.unary()
    if (!this.isOp('^')) return base
    this.take()
    const exponent = this.power()
    return { kind: 'binary', op: '^', left: base, right: exponent }
  }

  unary() {
    if (this.isOp('-') || this.isOp('+')) {
      const op = this.take().text
      return { kind: 'unary', op, operand: this.unary() }
    }
    return this.primary()
  }

  primary() {
    const token = this.peek()
    if (token === undefined) throw new SyntaxError('unexpected end of formula')
    if (token.kind === 'number') {
      this.take()
      return { kind: 'number', value: Number(token.text) }
    }
    if (token.kind === 'word') {
      if (this.isOp('(', 1)) return this.call()
      if (this.isOp(':', 1) && this.peek(2) !== undefined && this.peek(2).kind === 'word' && !this.isOp('(', 3)) {
        const from = this.take().text
        this.take()
        const to = this.take().text
        return { kind: 'range', from, to }
      }
      this.take()
      const upper = token.text.toUpperCase()
      if (upper === 'TRUE' || upper === 'FALSE') return { kind: 'boolean', value: upper === 'TRUE' }
      return { kind: 'reference', text: token.text }
    }
    if (token.kind === 'op' && token.text === '(') {
      this.take()
      const inner = this.comparison()
      if (!this.isOp(')')) throw new SyntaxError('expected )')
      this.take()
      return inner
    }
    throw new SyntaxError(`unexpected ${token.text}`)
  }

  call() {
    const name = this.take().text
    this.take()
    const args = []
    if (!this.isOp(')')) {
      args.push(this.comparison())
      while (this.isOp(',')) {
        this.take()
        args.push(this.comparison())
      }
    }
    if (!this.isOp(')')) throw new SyntaxError('expected )')
    this.take()
    return { kind: 'call', name, args }
  }
}

/** Parses a formula body, returning its tree or null when the grammar rejects it. */
export function parseFormula(body) {
  const tokens = tokenize(body)
  if (tokens === null) return null
  const parser = new Parser(tokens)
  try {
    const tree = parser.comparison()
    if (parser.at !== tokens.length) return null
    return tree
  } catch {
    return null
  }
}
"}

