{"file_path":"src/values.js","content":"/**
 * The values a cell can hold: numbers, text, booleans and errors.
 */

export const DIV0 = '#DIV/0!'
export const REF = '#REF!'
export const VALUE = '#VALUE!'
export const CYCLE = '#CYCLE!'
export const NAME = '#NAME?'
export const ERR = '#ERR!'

export const ERROR_TOKENS = [DIV0, REF, VALUE, CYCLE, NAME, ERR]

export const number = (value) => ({ kind: 'number', value })
export const text = (value) => ({ kind: 'text', value })
export const boolean = (value) => ({ kind: 'boolean', value })
export const error = (token) => ({ kind: 'error', value: token })

export const isError = (value) => value.kind === 'error'

const NUMBER_RE = /^-?[0-9]+(\.[0-9]+)?$/

/** Reads the content of a cell that is not a formula. */
export function literal(content) {
  if (content === '') return number(0)
  if (NUMBER_RE.test(content)) return number(Number(content))
  if (ERROR_TOKENS.includes(content)) return error(content)
  return text(content)
}

/** Reads a value in an arithmetic position, yielding an error value or a number. */
export function asNumber(value) {
  if (value.kind === 'number') return value
  if (value.kind === 'boolean') return number(value.value ? 1 : 0)
  if (value.kind === 'error') return value
  return error(VALUE)
}

/** An arithmetic result, which must be finite. */
export function finite(result) {
  if (!Number.isFinite(result)) return error(DIV0)
  return number(result)
}

const KIND_ORDER = { number: 0, text: 1, boolean: 2 }

function compareText(a, b) {
  const left = [...a]
  const right = [...b]
  const shared = Math.min(left.length, right.length)
  for (let i = 0; i < shared; i++) {
    const x = left[i].codePointAt(0)
    const y = right[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  if (left.length === right.length) return 0
  return left.length < right.length ? -1 : 1
}

/** Orders two values: numbers below text below booleans. */
export function compareValues(a, b) {
  if (a.kind !== b.kind) return KIND_ORDER[a.kind] < KIND_ORDER[b.kind] ? -1 : 1
  if (a.kind === 'number') return a.value === b.value ? 0 : a.value < b.value ? -1 : 1
  if (a.kind === 'text') return compareText(a.value, b.value)
  if (a.value === b.value) return 0
  return a.value ? 1 : -1
}

/** How a value is printed. */
export function format(value) {
  if (value.kind === 'number') {
    const rounded = value.value === 0 ? 0 : Number(value.value.toPrecision(10))
    return String(rounded === 0 ? 0 : rounded)
  }
  if (value.kind === 'boolean') return value.value ? 'TRUE' : 'FALSE'
  return value.value
}
"}

