{"file_path":"src/evaluator.js","content":"/**
 * Evaluating a sheet: the value of every cell, and the cells each one names.
 */

import { parseAddress, compareCells } from './sheet.js'
import { parseFormula } from './parser.js'
import {
  DIV0, REF, VALUE, CYCLE, NAME, ERR,
  number, text, boolean, error, isError,
  literal, asNumber, finite, compareValues,
} from './values.js'

const FUNCTIONS = {
  SUM: [1, Infinity],
  MIN: [1, Infinity],
  MAX: [1, Infinity],
  COUNT: [1, Infinity],
  AVG: [1, Infinity],
  ABS: [1, 1],
  IF: [3, 3],
}

function columnName(col) {
  let name = ''
  let rest = col
  while (rest > 0) {
    const step = (rest - 1) % 26
    name = String.fromCharCode(65 + step) + name
    rest = Math.floor((rest - 1) / 26)
  }
  return name
}

/** The cells a range covers, in column and then row order, or null when invalid. */
function expandRange(node) {
  const from = parseAddress(node.from)
  const to = parseAddress(node.to)
  if (from === null || to === null) return null
  const lowCol = Math.min(from.col, to.col)
  const highCol = Math.max(from.col, to.col)
  const lowRow = Math.min(from.row, to.row)
  const highRow = Math.max(from.row, to.row)
  const names = []
  for (let col = lowCol; col <= highCol; col++) {
    const letters = columnName(col)
    for (let row = lowRow; row <= highRow; row++) names.push(letters + String(row))
  }
  return names
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.trees = new Map()
    this.values = new Map()
    this.busy = new Set()
  }

  /** The parsed formula of a declared cell: `{ formula, tree }`. */
  treeOf(name) {
    if (this.trees.has(name)) return this.trees.get(name)
    const cell = this.cells.get(name)
    let entry
    if (cell === undefined || !cell.content.startsWith('=')) {
      entry = { formula: false, tree: null }
    } else {
      entry = { formula: true, tree: parseFormula(cell.content.slice(1)) }
    }
    this.trees.set(name, entry)
    return entry
  }

  /** The value of the cell named `name`, undeclared cells reading as zero. */
  valueOf(name) {
    if (this.values.has(name)) return this.values.get(name)
    const cell = this.cells.get(name)
    if (cell === undefined) return number(0)
    if (this.busy.has(name)) return error(CYCLE)
    this.busy.add(name)
    let value
    const entry = this.treeOf(name)
    if (!entry.formula) value = literal(cell.content)
    else if (entry.tree === null) value = error(ERR)
    else value = this.evaluate(entry.tree)
    this.busy.delete(name)
    this.values.set(name, value)
    return value
  }

  /** The values an argument contributes, a range contributing every cell it covers. */
  argumentValues(node) {
    if (node.kind === 'range') {
      const names = expandRange(node)
      if (names === null) return [error(REF)]
      return names.map((name) => this.valueOf(name))
    }
    return [this.evaluate(node)]
  }

  evaluate(node) {
    switch (node.kind) {
      case 'number':
        return number(node.value)
      case 'boolean':
        return boolean(node.value)
      case 'reference': {
        const address = parseAddress(node.text)
        if (address === null) return error(REF)
        return this.valueOf(address.name)
      }
      case 'range':
        return error(ERR)
      case 'unary': {
        const operand = asNumber(this.evaluate(node.operand))
        if (isError(operand)) return operand
        return finite(node.op === '-' ? -operand.value : operand.value)
      }
      case 'binary':
        return this.binary(node)
      case 'compare':
        return this.compare(node)
      case 'call':
        return this.call(node)
      default:
        return error(ERR)
    }
  }

  binary(node) {
    const left = asNumber(this.evaluate(node.left))
    if (isError(left)) return left
    const right = asNumber(this.evaluate(node.right))
    if (isError(right)) return right
    const a = left.value
    const b = right.value
    switch (node.op) {
      case '+':
        return finite(a + b)
      case '-':
        return finite(a - b)
      case '*':
        return finite(a * b)
      case '/':
        if (b === 0) return error(DIV0)
        return finite(a / b)
      case '^':
        return finite(a ** b)
      default:
        return error(ERR)
    }
  }

  compare(node) {
    const left = this.evaluate(node.left)
    if (isError(left)) return left
    const right = this.evaluate(node.right)
    if (isError(right)) return right
    const order = compareValues(left, right)
    switch (node.op) {
      case '=':
        return boolean(order === 0)
      case '<>':
        return boolean(order !== 0)
      case '<':
        return boolean(order < 0)
      case '<=':
        return boolean(order <= 0)
      case '>':
        return boolean(order > 0)
      case '>=':
        return boolean(order >= 0)
      default:
        return error(ERR)
    }
