    const values = []
    for (const arg of node.args) {
      for (const value of this.argumentValues(arg)) {
        if (isError(value)) return value
        values.push(value)
      }
    }

    if (name === 'COUNT') {
      return number(values.filter((value) => value.kind === 'number').length)
    }

    const numbers = []
    for (const value of values) {
      const read = asNumber(value)
      if (isError(read)) return read
      numbers.push(read.value)
    }

    switch (name) {
      case 'SUM':
        return finite(numbers.reduce((total, x) => total + x, 0))
      case 'MIN':
        return finite(numbers.reduce((best, x) => (x < best ? x : best)))
      case 'MAX':
        return finite(numbers.reduce((best, x) => (x > best ? x : best)))
      case 'AVG':
        return finite(numbers.reduce((total, x) => total + x, 0) / numbers.length)
      case 'ABS':
        return finite(Math.abs(numbers[0]))
      default:
        return error(ERR)
    }
  }

  conditional(node) {
    const conditions = this.argumentValues(node.args[0])
    for (const value of conditions) if (isError(value)) return value
    const first = conditions[0]
    let taken
    if (first.kind === 'boolean') taken = first.value
    else if (first.kind === 'number') taken = first.value !== 0
    else return error(VALUE)
    const results = this.argumentValues(taken ? node.args[1] : node.args[2])
    for (const value of results) if (isError(value)) return value
    return results[0]
  }

  /** The distinct cells a cell names directly, in column and then row order. */
  dependencies(name) {
    const entry = this.treeOf(name)
    if (!entry.formula || entry.tree === null) return []
    const found = new Map()
    const walk = (node) => {
      switch (node.kind) {
        case 'reference': {
          const address = parseAddress(node.text)
          if (address !== null) found.set(address.name, address)
          break
        }
        case 'range': {
          const names = expandRange(node)
          if (names !== null) {
            for (const covered of names) found.set(covered, parseAddress(covered))
          }
          break
        }
        case 'unary':
          walk(node.operand)
          break
        case 'binary':
        case 'compare':
          walk(node.left)
          walk(node.right)
          break
        case 'call':
          for (const arg of node.args) walk(arg)
          break
        default:
          break
      }
    }
    walk(entry.tree)
    return [...found.values()].sort(compareCells).map((address) => address.name)
  }
}

