/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, orderedCells } from './sheet.js'
import { Sheet } from './evaluator.js'
import { format } from './values.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readInput() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'values' && mode !== 'deps')) {
    fail('usage: cli.js values|deps')
  }

  const parsed = parseSheet(readInput())
  if (parsed.error !== undefined) fail(parsed.error)

  const sheet = new Sheet(parsed.cells)
  const lines = []
  for (const cell of orderedCells(parsed.cells)) {
    if (mode === 'values') {
      lines.push(`${cell.name}=${format(sheet.valueOf(cell.name))}`)
    } else {
      const named = sheet.dependencies(cell.name)
      lines.push(`${cell.name}:${named.map((name) => ` ${name}`).join('')}`)
    }
  }
  if (lines.length > 0) process.stdout.write(lines.join('\n') + '\n')
}

main(process.argv.slice(2))
